                const a = (i / N) * Math.PI * 2;
                const sw = WALL_T * (1.45 + 0.55 * jit(i, 1));
                const sh = RIM_H * (0.80 + 0.36 * jit(i, 2));
                const sd = WALL_T * (0.95 + 0.40 * jit(i, 3));
